207	            return Err(OptionsError::Unsupported(String::from(
208	                "Options --git and --git-ignore can't be used because `git` feature was disabled in this build of exa",
209	            )));
210	        }
211	        let view = View::deduce(matches, vars)?;
212	        let dir_action = DirAction::deduce(matches, matches!(view.mode, Mode::Details(_)))?;
213	        let filter = FileFilter::deduce(matches)?;
214	        let theme = ThemeOptions::deduce(matches, vars)?;
215	        let stdin = FilesInput::deduce(matches, vars)?;
216	
217	        Ok(Self {
218	            dir_action,
219	            filter,
220	            view,
221	            theme,
222	            stdin,
223	        })
