29	            (matches.has(&flags::DIRS_LAST)?, FFF::ListDirsLast),
30	            (matches.has(&flags::DIRS_FIRST)?, FFF::ListDirsFirst),
31	        ] {
32	            if *has {
33	                filter_flags.push(flag.clone());
34	            }
35	        }
36	
37	        #[rustfmt::skip]
38	        return Ok(Self {
39	            no_symlinks:      filter_flags.contains(&FFF::NoSymlinks),
40	            show_symlinks:    filter_flags.contains(&FFF::ShowSymlinks),
41	            flags:            filter_flags,
