338	impl IgnorePatterns {
339	    /// Create a new list from the input glob strings, turning the inputs that
340	    /// are valid glob patterns into an `IgnorePatterns`. The inputs that
341	    /// don’t parse correctly are returned separately.
342	    pub fn parse_from_iter<'a, I: IntoIterator<Item = &'a str>>(
343	        iter: I,
344	    ) -> (Self, Vec<glob::PatternError>) {
345	        let iter = iter.into_iter();
346	
347	        // Almost all glob patterns are valid, so it’s worth pre-allocating
348	        // the vector with enough space for all of them.
349	        let mut patterns = match iter.size_hint() {
350	            (_, Some(count)) => Vec::with_capacity(count),
351	            _ => Vec::new(),
352	        };
353	
354	        // Similarly, assume there won’t be any errors.
355	        let mut errors = Vec::new();
356	
357	        for input in iter {
358	            match glob::Pattern::new(input) {
359	                Ok(pat) => patterns.push(pat),
360	                Err(e) => errors.push(e),
361	            }
362	        }
363	
364	        (Self { patterns }, errors)
365	    }
366	
367	    /// Create a new empty set of patterns that matches nothing.
368	    #[must_use]
369	    pub fn empty() -> Self {
370	        Self {
371	            patterns: Vec::new(),
372	        }
373	    }
374	
375	    /// Test whether the given file should be hidden from the results.
376	    fn is_ignored(&self, file: &str) -> bool {
377	        self.patterns.iter().any(|p| p.matches(file))
378	    }
