7	//! What to do when encountering a directory?
8	
9	/// The action to take when trying to list a file that turns out to be a
10	/// directory.
11	///
12	/// By default, exa will display the information about files passed in as
13	/// command-line arguments, with one file per entry. However, if a directory
14	/// is passed in, exa assumes that the user wants to see its contents, rather
15	/// than the directory itself.
16	///
17	/// This can get annoying sometimes: if a user does `exa ~/Downloads/img-*`
18	/// to see the details of every file starting with `img-`, any directories
19	/// that happen to start with the same will be listed after the files at
20	/// the end in a separate block. By listing directories as files, their
21	/// directory status will be ignored, and both will be listed side-by-side.
22	///
23	/// These two modes have recursive analogues in the “recurse” and “tree”
24	/// modes. Here, instead of just listing the directories, exa will descend
25	/// into them and print out their contents. The recurse mode does this by
26	/// having extra output blocks at the end, while the tree mode will show
27	/// directories inline, with their contents immediately underneath.
28	#[derive(PartialEq, Eq, Debug, Copy, Clone)]
29	pub enum DirAction {
30	    /// This directory should be listed along with the regular files, instead
31	    /// of having its contents queried.
32	    AsFile,
33	
34	    /// This directory should not be listed, and should instead be opened and
35	    /// *its* files listed separately. This is the default behaviour.
36	    List,
37	
38	    /// This directory should be listed along with the regular files, and then
39	    /// its contents should be listed afterward. The recursive contents of
40	    /// *those* contents are dictated by the options argument.
41	    Recurse(RecurseOptions),
42	}
43	
44	impl DirAction {
45	    /// Gets the recurse options, if this dir action has any.
46	    #[must_use]
47	    pub fn recurse_options(self) -> Option<RecurseOptions> {
48	        match self {
49	            Self::Recurse(o) => Some(o),
50	            _ => None,
51	        }
